"use client";

import { FormEvent, useState } from "react";
import Link from "next/link";

const events = [
  { id: "mehndi", name: "Mehndi", number: "01", accent: "saffron", copy: "Details to follow" },
  { id: "jaggo", name: "Jaggo", number: "02", accent: "rose", copy: "Details to follow" },
  { id: "anandKaraj", name: "Anand Karaj", number: "03", accent: "marigold", copy: "Details to follow" },
  { id: "reception", name: "Reception", number: "04", accent: "coral", copy: "Details to follow" },
] as const;

type EventId = (typeof events)[number]["id"];
type Attendance = Record<EventId, "yes" | "no" | "">;
const initialAttendance: Attendance = { mehndi: "", jaggo: "", anandKaraj: "", reception: "" };

export default function RSVPPage() {
  const [sent, setSent] = useState(false);
  const [submitting, setSubmitting] = useState(false);
  const [error, setError] = useState("");
  const [name, setName] = useState("");
  const [phone, setPhone] = useState("");
  const [attendance, setAttendance] = useState<Attendance>(initialAttendance);
  const [message, setMessage] = useState("");

  function setEventAttendance(id: EventId, value: "yes" | "no") {
    setAttendance((current) => ({ ...current, [id]: value }));
    setError("");
  }

  async function submitRsvp(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    if (!name.trim() || !phone.trim() || Object.values(attendance).some((value) => !value)) {
      setError("Please add your details and choose an answer for each celebration.");
      return;
    }
    setSubmitting(true);
    setError("");
    try {
      const response = await fetch("/api/rsvp", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ name, phone, events: attendance, message }) });
      if (!response.ok) throw new Error("RSVP could not be sent");
      setSent(true);
    } catch {
      setError("We could not send that just now. Please try again in a moment.");
    } finally {
      setSubmitting(false);
    }
  }

  return <main className="invitation revealed" id="celebrations">
    <div className="section-intro"><Link className="back-link" href="/">← Back to invitation</Link><p className="eyebrow">The celebrations</p><h1>Let the celebrations<br /><i>begin.</i></h1><p>Four celebrations. One unforgettable journey.<br />We&apos;d love to have you with us.</p></div>
    <div className="event-grid">{events.map((event) => <article className={`event-card ${event.accent}`} key={event.id}><div className="event-art" aria-hidden="true"><span>{event.number}</span><strong>{event.name === "Anand Karaj" ? "A K" : event.name.slice(0, 2).toUpperCase()}</strong></div><div className="event-content"><p className="event-number">Chapter {event.number}</p><h2>{event.name}</h2><p className="event-detail">{event.copy}<br />Date · time · venue to follow</p></div></article>)}</div>
    <form className="rsvp" onSubmit={submitRsvp}>{!sent ? <><div className="rsvp-heading"><p className="eyebrow">Your reply</p><h2>Will you join us?</h2><p>One reply for every celebration.</p></div><div className="fields"><label>Full name<input value={name} onChange={(e) => setName(e.target.value)} placeholder="Your name" autoComplete="name" /></label><label>Phone number<input value={phone} onChange={(e) => setPhone(e.target.value)} placeholder="Your number" type="tel" autoComplete="tel" /></label></div><div className="attendance-list">{events.map((event) => <fieldset key={event.id}><legend>{event.name}</legend><div className="choice-group"><button type="button" className={attendance[event.id] === "yes" ? "selected" : ""} onClick={() => setEventAttendance(event.id, "yes")} aria-pressed={attendance[event.id] === "yes"}>Joyfully attending</button><button type="button" className={attendance[event.id] === "no" ? "selected" : ""} onClick={() => setEventAttendance(event.id, "no")} aria-pressed={attendance[event.id] === "no"}>Unable to attend</button></div></fieldset>)}</div><label className="message-field">A note for the couple <textarea value={message} onChange={(e) => setMessage(e.target.value)} placeholder="Leave a little love (optional)" rows={3} /></label>{error && <p className="form-error" role="alert">{error}</p>}<button className="submit-button" type="submit" disabled={submitting}>{submitting ? "Sending your reply..." : "Send my RSVP  →"}</button></> : <div className="confirmation"><span className="confirmation-mark">✦</span><p className="eyebrow">Your reply is in</p><h2>You&apos;re on<br /><i>the list.</i></h2><p>Thank you for letting us celebrate these special moments with you.</p></div>}</form>
    <footer>Sukhvir <span>+</span> Amrit <small>Made with love</small></footer>
  </main>;
}